insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-BIO-L1', 'Unit 1 Transport in plants and plant nutrients: How water and minerals reach the leaves', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 4, "n": 4, "ans": ["False", "True", "True", "False"], "tip": "Roots in, leaves out."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["Root hair cell", "Xylem", "Stomata", "Leaf"], "tip": "Follow the water from soil to air."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["long", "thin", "extension", "hair"], ["surface area"]], "tips": ["Shape → surface area → absorption."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 5, "n": 5, "ans": ["Faster", "Slower", "Faster", "Slower", "Slower"], "tip": "Think of drying washing."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 3, "pts": [["7.5"], ["wind", "fan", "moving air"], ["evaporat", "water vapour", "blown away", "carried away"]], "tips": ["Distance ÷ time, then why."]}], "4": [{"kind": "choice", "id": "q4_0", "q": "Q7", "max": 4, "n": 4, "ans": ["Magnesium", "Nitrate", "Nitrate", "Magnesium"], "tip": "Chlorophyll or protein?"}, {"kind": "text", "id": "q4_1", "q": "Q8", "max": 3, "pts": [["chlorophyll"], ["photosynthesis", "absorb light", "trap light"], ["glucose", "food", "sugar", "energy"]], "tips": ["Magnesium → chlorophyll → photosynthesis."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 4, "pts": [["potometer", "bubble", "mass", "balance"], ["temperature", "different temperatures", "water bath"], ["same", "keep", "control", "fair"], ["repeat", "average", "mean"]], "tips": ["Change, measure, keep the same, repeat."]}]}, "models": {"1": [["Q1", "Red dots near the outside of the stalk: the xylem vessels carrying the coloured water."], ["Q2", "Water enters through the roots, travels in the xylem and most is lost from the leaves; there is no pump."]], "2": [["Q3", "Root hair cells absorb; xylem carries; water evaporates from the leaf through the stomata."], ["Q4", "It has a long, thin extension (the root hair) [1] which gives a large surface area so more water can be absorbed [1]."]], "3": [["Q5", "Heat, wind and light speed it up; humidity, darkness and blocking the stomata slow it down."], ["Q6", "Rate = 75 ÷ 10 = 7.5 mm per minute [1]; the moving air from the fan [1] carries water vapour away from the leaf so more water evaporates and more is pulled up [1]."]], "4": [["Q7", "Magnesium → chlorophyll (green colour); nitrate → protein (growth)."], ["Q8", "Magnesium is needed to make chlorophyll [1]; with less chlorophyll the plant absorbs less light for photosynthesis [1], so it makes less glucose for energy and growth [1]."]], "5": [["Q9", "Use a potometer and measure how far the bubble moves in a set time [1]; change the temperature of the room or air around the shoot, e.g. 10, 20, 30 °C [1]; keep the same shoot (or same size), light intensity and air movement [1]; repeat each temperature and calculate a mean [1]."]], "6": [["Exit ticket", "Xylem; transpiration (evaporation of water from the leaves)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Predict what you would see if you cut across a celery stalk that has stood in red ink for a day.", "Q2": "True or false?", "Q3": "Match the structure to its job.", "Q4": "Explain how the shape of a root hair cell helps it to absorb water.", "Q5": "Faster or slower transpiration?", "Q6": "A student puts a leafy shoot in a potometer. The bubble moves 30 mm in 10 minutes in still air and 75 mm in 10 minutes with a fan. Calculate the rate with the fan and explain the difference.", "Q7": "Which mineral is missing?", "Q8": "Explain why a plant grown without magnesium grows poorly.", "Q9": "Plan an investigation to find out how temperature affects the rate of transpiration of a leafy shoot."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
