insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('e0a26154-7716-593e-9e57-f4f9925e19ac', '74d6d902-7f4f-5d7b-83c4-1cb518341b0f', 'short', 'A farmer notices that her maize plants are small with yellow lower leaves. Suggest which mineral is lacking and explain why the plants are small.', '[]'::jsonb, 3, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e0a26154-7716-593e-9e57-f4f9925e19ac', 'Nitrate is lacking [1]; nitrates are needed to make proteins [1], which are needed for growth of new cells, so the plants stay small [1].', 'Nitrate is lacking [1]; nitrates are needed to make proteins [1], which are needed for growth of new cells, so the plants stay small [1].', '[{"text": "Nitrate is lacking", "any": ["nitrate", "nitrogen"], "all": [], "marks": 1}, {"text": "Nitrates are needed to make proteins", "any": ["protein"], "all": [], "marks": 1}, {"text": "Which are needed for growth of new cells, so the plants stay small", "any": ["growth", "grow", "cells"], "all": [], "marks": 1}]'::jsonb, 'Nitrate is lacking [1]; nitrates are needed to make proteins [1], which are needed for growth of new cells, so the plants stay small [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
