insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('3dcb0aa0-d23d-5f1a-8bf9-8bcb2d0dec71', '74d6d902-7f4f-5d7b-83c4-1cb518341b0f', 'short', 'Describe how water moves from the soil to the air around a leaf.', '[]'::jsonb, 4, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('3dcb0aa0-d23d-5f1a-8bf9-8bcb2d0dec71', 'Water is absorbed into root hair cells by osmosis [1]; it travels up the stem in the xylem [1]; it evaporates from the cells inside the leaf [1] and the water vapour diffuses out through the stomata [1].', 'Water is absorbed into root hair cells by osmosis [1]; it travels up the stem in the xylem [1]; it evaporates from the cells inside the leaf [1] and the water vapour diffuses out through the stomata [1].', '[{"text": "Water is absorbed into root hair cells by osmosis", "any": ["root hair", "osmosis", "absorb"], "all": [], "marks": 1}, {"text": "It travels up the stem in the xylem", "any": ["xylem"], "all": [], "marks": 1}, {"text": "It evaporates from the cells inside the leaf", "any": ["evaporat"], "all": [], "marks": 1}, {"text": "The water vapour diffuses out through the stomata", "any": ["stomata"], "all": [], "marks": 1}]'::jsonb, 'Water is absorbed into root hair cells by osmosis [1]; it travels up the stem in the xylem [1]; it evaporates from the cells inside the leaf [1] and the water vapour diffuses out through the stomata [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
