insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('c1cd752f-202a-5b57-a2b9-fe989b8ec7b5', '85ab2f17-1865-5837-a551-1f5570a233b8', 'Unit 2 Photosynthesis: How plants make their food', 'Stage 9 Biology · Objectives 9Bp.06, 9Bp.07', '/cks9-bio-2/', 'CKS9-BIO-L2', 19, 60, 20) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-BIO-L2', 'Unit 2 Photosynthesis: How plants make their food', '{"marks": {"1": [{"kind": "choice", "id": "q1_1", "q": "Q2", "max": 3, "n": 3, "ans": ["Carbon dioxide", "Light", "Water"], "tip": "Look at the elements."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 3, "n": 3, "ans": ["water", "glucose", "oxygen"], "tip": "Two in, two out."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["top", "upper", "near the surface", "most light"], ["photosynthesis", "absorb light", "chlorophyll"]], "tips": ["Position + job."]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Kills the leaf and softens it", "Removes the green colour", "Shows where starch is", "Safety"], "tip": "Each step has one job."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["dark", "no light"], ["no photosynthesis", "used up", "no starch", "not made"]], "tips": ["No light → ?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 2, "pts": [["more light", "light intensity", "brighter"], ["faster photosynthesis", "more oxygen", "rate increase"]], "tips": ["Distance → light → rate."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q9", "max": 3, "pts": [["limiting", "another factor", "something else"], ["carbon dioxide", "temperature"], ["increase", "add", "raise", "warmer", "more"]], "tips": ["What limits it now?"]}]}, "models": {"1": [["Q1", "Carbon dioxide from the air, which provides the carbon for glucose and the rest of the plant''s mass."], ["Q2", "Carbon from carbon dioxide, hydrogen from water, energy from light."]], "2": [["Q3", "carbon dioxide + water → glucose + oxygen."], ["Q4", "Palisade cells are near the top of the leaf where they receive the most light [1]; more chloroplasts mean more chlorophyll to absorb light for photosynthesis [1]."]], "3": [["Q5", "Water kills/softens; ethanol removes chlorophyll; iodine shows starch; water bath because ethanol is flammable."], ["Q6", "In the dark there is no light so no photosynthesis [1]; the starch already stored was used up, so none is left to turn iodine blue-black [1]."]], "4": [["Q7", "Closer to the lamp the light intensity is greater [1], so the rate of photosynthesis increases and more oxygen bubbles are made [1]."], ["Q8", "Add carbon dioxide (e.g. paraffin heater), extra lighting or heating: each supplies more of a factor that may be limiting."]], "5": [["Q9", "Light is no longer the limiting factor; another factor is limiting [1], such as carbon dioxide concentration or temperature [1]; increasing the carbon dioxide concentration or raising the temperature (not too high) would increase the rate further [1]."]], "6": [["Exit ticket", "carbon dioxide + water → glucose + oxygen (light energy, chlorophyll)."]]}, "labels": {"q1_0": "Q1", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q4_1": "Q8", "q5_0": "Q9", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Van Helmont thought the tree''s mass came only from water. What did he not know about?", "Q2": "Which raw material provides…", "Q3": "Complete the word equation: carbon dioxide + ___ → ___ + ___", "Q4": "Explain why palisade cells contain many chloroplasts.", "Q5": "Why is each step done?", "Q6": "A plant is kept in the dark for 48 hours, then one leaf is tested for starch. The iodine stays orange-brown. Explain this result.", "Q7": "A lamp is moved from 40 cm to 10 cm from some pondweed. The bubbles increase from 8 to 30 per minute. Explain this result.", "Q8": "Suggest one thing a greenhouse grower can do to increase the rate of photosynthesis, and why it works.", "Q9": "The rate of photosynthesis rises as light intensity increases, then stays the same however bright the light becomes. Explain why the graph levels off and suggest how the rate could be increased further."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
