insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('9489a63e-fd3d-5a23-a2cc-a964a45c8bfe', '34880988-7e3f-5582-81f1-ec8e0d5e0aff', 'Unit 3 Excretion: the kidneys: Cleaning the blood', 'Stage 9 Biology · Objectives 9Bs.02', '/cks9-bio-3/', 'CKS9-BIO-L3', 23, 60, 30) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-BIO-L3', 'Unit 3 Excretion: the kidneys: Cleaning the blood', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Kidneys", "Lungs", "Kidneys", "Kidneys"], "tip": "Gas or dissolved?"}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 5, "n": 5, "ans": ["Bladder", "Ureter", "Urethra", "Kidney", "Renal artery"], "tip": "Follow the urine."}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q4", "max": 5, "n": 5, "ans": ["Present", "Present", "Absent", "Absent", "Absent"], "tip": "Too big or all taken back?"}, {"kind": "text", "id": "q3_1", "q": "Q5", "max": 2, "pts": [["small", "filtered", "squeezed"], ["reabsorb", "taken back", "back into the blood"]], "tips": ["Filtered, then…"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q6", "max": 3, "pts": [["less", "smaller volume"], ["concentrated", "darker", "stronger"], ["water", "sweat", "lost"]], "tips": ["Water out as sweat → ?"]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q7", "max": 4, "pts": [["dialysis+available", "no waiting", "no donor", "no operation"], ["dialysis+time", "hours", "three times", "expensive", "diet"], ["transplant+permanent", "normal life", "free", "cure"], ["reject", "donor", "waiting", "drugs", "operation"]], "tips": ["Two for each."]}]}, "models": {"1": [["Q1", "Carbon dioxide leaves through the lungs; urea, excess water and salt leave through the kidneys."], ["Q2", "Faeces are mostly undigested food that never entered the body''s cells; excretion removes waste made by chemical reactions in cells."]], "2": [["Q3", "Renal artery → kidney → ureter → bladder → urethra."]], "3": [["Q4", "Urea, water and some salt are present; glucose is all reabsorbed; cells and proteins are too big to be filtered."], ["Q5", "Glucose molecules are small enough to be filtered out of the blood [1], but all of it is reabsorbed (taken back) into the blood because the body needs it [1]."]], "4": [["Q6", "She makes a smaller volume of urine [1] that is more concentrated (darker) [1] because water has been lost in sweat, so the kidneys reabsorb more water to keep it in the body [1]."]], "5": [["Q7", "Dialysis is available without waiting for a donor [1] but takes hours several times a week and limits diet [1]; a transplant can give a normal life without machines [1] but needs a matching donor and drugs to stop rejection [1]."]], "6": [["Exit ticket", "Urea; the bladder."]]}, "labels": {"q1_1": "Q2", "q3_1": "Q5", "q4_0": "Q6", "q5_0": "Q7", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which organ excretes it?", "Q2": "Why is getting rid of faeces not called excretion?", "Q3": "Name the part.", "Q4": "In healthy urine?", "Q5": "Explain why glucose is filtered out of the blood but is not found in the urine of a healthy person.", "Q6": "On a hot day Amina sweats a lot. Describe and explain how her urine changes.", "Q7": "Compare dialysis and a kidney transplant as treatments for kidney failure. Give one advantage and one disadvantage of each."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
