insert into public.questions (id, topic_id, kind, prompt, options, marks, section, created_by) values ('75544762-a738-5c9e-8c5a-dab010cd7eb4', '34880988-7e3f-5582-81f1-ec8e0d5e0aff', 'short', 'The table compares blood entering the kidney and urine. Glucose: 1.0 g/l in blood, 0 g/l in urine. Urea: 0.3 g/l in blood, 20 g/l in urine. Explain the difference for each substance.', '[]'::jsonb, 4, 'Checkpoint-style', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, section = excluded.section, topic_id = excluded.topic_id;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('75544762-a738-5c9e-8c5a-dab010cd7eb4', 'All the glucose is reabsorbed into the blood [1] because the body needs it for respiration [1]; urea is more concentrated in urine because most of the water is reabsorbed [1] and urea is a toxic waste that is removed [1].', 'All the glucose is reabsorbed into the blood [1] because the body needs it for respiration [1]; urea is more concentrated in urine because most of the water is reabsorbed [1] and urea is a toxic waste that is removed [1].', '[{"text": "All the glucose is reabsorbed into the blood", "any": [], "all": ["glucose", "reabsorb"], "marks": 1}, {"text": "Because the body needs it for respiration", "any": ["needed", "useful", "respiration"], "all": [], "marks": 1}, {"text": "Urea is more concentrated in urine because most of the water is reabsorbed", "any": ["water taken back"], "all": [], "marks": 1}, {"text": "Urea is a toxic waste that is removed", "any": ["waste", "toxic", "removed"], "all": [], "marks": 1}]'::jsonb, 'All the glucose is reabsorbed into the blood [1] because the body needs it for respiration [1]; urea is more concentrated in urine because most of the water is reabsorbed [1] and urea is a toxic waste that is removed [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
