insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('7de4ac89-6dbb-5bb2-b106-37038886d4f9', 'Without working kidneys urea (and excess water and salt) is not removed [1], so it builds up in the blood and becomes toxic [1].', 'Without working kidneys urea (and excess water and salt) is not removed [1], so it builds up in the blood and becomes toxic [1].', '[{"text": "Without working kidneys urea (and excess water and salt) is not removed", "any": ["urea", "waste", "toxin"], "all": [], "marks": 1}, {"text": "It builds up in the blood and becomes toxic", "any": ["build up", "builds up", "accumulat", "poison"], "all": [], "marks": 1}]'::jsonb, 'Without working kidneys urea (and excess water and salt) is not removed [1], so it builds up in the blood and becomes toxic [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
