insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-BIO-L4', 'Unit 4 Chromosomes, genes and inheritance: Instructions from both parents', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Smallest", "Middle", "Largest", "Contains all the others"], "tip": "Gene is part of a chromosome."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q3", "max": 4, "n": 4, "ans": ["23", "23", "46", "46"], "tip": "Gametes have half."}, {"kind": "text", "id": "q2_1", "q": "Q4", "max": 2, "pts": [["23", "half"], ["fuse", "join", "combine", "add"]], "tips": ["What do gametes carry?"]}], "3": [{"kind": "choice", "id": "q3_0", "q": "Q5", "max": 4, "n": 4, "ans": ["Girl", "Boy", "Girl", "Boy"], "tip": "Y makes a boy."}, {"kind": "text", "id": "q3_1", "q": "Q6", "max": 2, "pts": [["50", "half", "1 in 2", "one in two"], ["each", "every", "independent", "not affected", "does not depend", "separate"]], "tips": ["Does the past change the chance?"]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q7", "max": 3, "pts": [["x and x", "x, x", "egg+x"], ["x and y", "x, y", "sperm+y"], ["1:1", "1 : 1", "50", "half", "2:2", "2 : 2"]], "tips": ["Gametes, square, ratio."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q8", "max": 3, "pts": [["egg+x", "mother+x", "only x"], ["sperm+y", "half the sperm", "x or y"], ["y+boy", "decides", "determines", "father"]], "tips": ["What can each parent give?"]}]}, "models": {"1": [["Q1", "Gene → chromosome → nucleus → cell."], ["Q2", "Half of their chromosomes (and genes) come from each parent."]], "2": [["Q3", "Gametes have 23; body cells and the fertilised egg have 46."], ["Q4", "Each gamete has only 23 chromosomes, half the normal number [1]; when the sperm and egg nuclei fuse, 23 + 23 = 46 [1]."]], "3": [["Q5", "XX is a girl, XY is a boy; the Y comes from the sperm."], ["Q6", "The chance is 50% (1 in 2) [1] because each fertilisation is separate: half the sperm carry Y, whatever happened before [1]."]], "4": [["Q7", "The mother''s gametes are X and X [1]; the father''s gametes are X and Y [1]; the offspring are XX, XX, XY, XY so the ratio of boys to girls is 1 : 1 (50% each) [1]."]], "5": [["Q8", "Every egg from the mother carries an X chromosome [1]; half the father''s sperm carry X and half carry Y [1]; so whether the sperm that fertilises the egg carries X or Y decides whether the baby is a girl or a boy [1]."]], "6": [["Exit ticket", "XY."]]}, "labels": {"q1_1": "Q2", "q2_1": "Q4", "q3_1": "Q6", "q4_0": "Q7", "q5_0": "Q8", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Put them in order of size, smallest first.", "Q2": "Why do you think children share some characteristics with each parent?", "Q3": "How many chromosomes?", "Q4": "Explain why a fertilised egg has 46 chromosomes and not 92.", "Q5": "Boy or girl?", "Q6": "A couple already have three daughters. Explain the chance that their next child will be a boy.", "Q7": "Complete a genetic diagram in your book for a mother (XX) and a father (XY). State the gametes of each parent and the ratio of boys to girls.", "Q8": "Use your knowledge of sex chromosomes to explain why the sex of a baby depends on the father''s sperm and not on the mother."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
