insert into public.lessons (id, topic_id, title, summary, url, external_id, max_marks, minutes, sort_order) values ('c55d4fd8-01e7-5a32-9e30-18beb570b463', 'ff43db0a-9a44-5a65-86a1-62a215649975', 'Unit 6 Growth of the fetus and the mother''s health: Growing safely in the womb', 'Stage 9 Biology · Objectives 9Bp.08', '/cks9-bio-6/', 'CKS9-BIO-L6', 16, 60, 60) on conflict (external_id) do update set title = excluded.title, summary = excluded.summary, url = excluded.url, max_marks = excluded.max_marks, minutes = excluded.minutes, topic_id = excluded.topic_id, sort_order = excluded.sort_order;
insert into public.lesson_specs (lesson, title, spec, updated_at) values ('CKS9-BIO-L6', 'Unit 6 Growth of the fetus and the mother''s health: Growing safely in the womb', '{"marks": {"1": [{"kind": "choice", "id": "q1_0", "q": "Q1", "max": 4, "n": 4, "ans": ["Mother → fetus", "Mother → fetus", "Fetus → mother", "Fetus → mother"], "tip": "Food and oxygen in, waste out."}], "2": [{"kind": "choice", "id": "q2_0", "q": "Q2", "max": 4, "n": 4, "ans": ["Iron", "Calcium", "Protein", "Folic acid"], "tip": "Match nutrient to job."}], "3": [{"kind": "text", "id": "q3_0", "q": "Q3", "max": 3, "pts": [["carbon monoxide", "nicotine"], ["less oxygen", "oxygen"], ["growth", "grow", "respiration", "energy"]], "tips": ["Smoke → blood → oxygen → growth."]}], "4": [{"kind": "text", "id": "q4_0", "q": "Q4", "max": 2, "pts": [["more", "increase", "heavier smok"], ["0.4", "3.4", "3.0", "400"]], "tips": ["Trend + figures."]}], "5": [{"kind": "text", "id": "q5_0", "q": "Q6", "max": 3, "pts": [["smok", "cigarette"], ["alcohol", "drink"], ["diet", "iron", "calcium", "protein", "folic", "vitamin", "drug", "medicine"]], "tips": ["Advice + because…"]}]}, "models": {"1": [["Q1", "Oxygen and nutrients go to the fetus; carbon dioxide and urea go to the mother."]], "2": [["Q2", "Iron → blood; calcium → bones; protein → growth; folic acid → nervous system."]], "3": [["Q3", "Carbon monoxide in smoke reduces how much oxygen the mother''s blood carries (and nicotine narrows blood vessels) [1], so less oxygen crosses the placenta to the fetus [1]; with less oxygen for respiration the fetus grows less [1]."]], "4": [["Q4", "The more cigarettes the mother smokes, the lower the mean birth mass [1]; it falls from 3.4 kg for non-smokers to 3.0 kg for more than 10 a day, a drop of 0.4 kg [1]."], ["Q5", "One case is not enough; the data from thousands of births show a clear average effect; other factors also affect birth mass."]], "5": [["Q6", "Do not smoke, because carbon monoxide and nicotine reduce the oxygen reaching the fetus [1]; avoid alcohol, because it crosses the placenta and can damage the fetus''s brain [1]; eat a balanced diet with extra protein, iron, calcium and folic acid for the fetus''s growth (and only take medicines a doctor approves) [1]."]], "6": [["Exit ticket", "The placenta."]]}, "labels": {"q3_0": "Q3", "q4_0": "Q4", "q4_1": "Q5", "q5_0": "Q6", "q6_0": "Exit ticket", "s6rev": "Revision plan", "s6q": "Question"}, "questions": {"Q1": "Which direction across the placenta?", "Q2": "Why is the nutrient needed?", "Q3": "Explain why babies of mothers who smoke often have a lower birth mass.", "Q4": "Use the data to describe the effect of smoking on birth mass. Use numbers in your answer.", "Q5": "A student says: \"My aunt smoked and her baby was 4 kg, so smoking does not matter.\" Why is this not a good conclusion?", "Q6": "Write three pieces of advice for a pregnant woman, each with a scientific reason."}}'::jsonb, now()) on conflict (lesson) do update set title = excluded.title, spec = excluded.spec, updated_at = now();
